/**
 * Crow Studio — the panel's local-first take store, as one inline classic
 * script.
 *
 * A recording must survive the network being down when it starts, dropping
 * mid-take, or the tab being closed (spec §5.7, Review Focus 1). So every chunk
 * of every take is written here first, in the page's own IndexedDB, under the
 * take id the client generated; the upload to the gateway comes afterwards and
 * can be retried, resumed on the next page load, or never happen at all. What
 * is on this device is the source of truth until `finish` returns a take.
 *
 * Like `panel/client.js` this travels as a string (`TAKE_STORE_SCRIPT`) and is
 * written as an EXPRESSIONS ONLY classic script: no backtick, no `${`, no
 * double quote and no backslash anywhere in the emitted text. It assigns one
 * global — `window.StudioTakeStore` — and builds nothing in the DOM.
 *
 * ## Database
 *
 * One IndexedDB database, `studio`, version 1, with four object stores:
 *
 *   - `chunks`  keyed `[take_id, index]`, value: the chunk's ArrayBuffer
 *               (24-bit little-endian interleaved PCM, as the recorder posts
 *               it). The index restarts at 0 for each take (each loop pass is
 *               its own take).
 *   - `pending` keyed `take_id`, value:
 *               `{take_id, song_id, clip_id, rate, channels, offset_frames,
 *                 compensated, bpm, chunk_count, begun, finished,
 *                 created_at}` — what an upload needs to be resumed after a
 *               reload, or after the tab was closed mid-take. `chunk_count` is
 *               null until the recorder reported the take's end.
 *   - `latency` keyed by `"<input label>|<output label or sink id>|<rate>|
 *               <latency hint>"`, value: `{latency_frames, rate,
 *               spread_frames, measured_at}` — one measurement per input,
 *               output, rate and hint (spec §5.7: stored per device and
 *               interface).
 *   - `audio`   keyed `take_id`, value: the take's WAV bytes, cached so a
 *               reload does not fetch it again (the takes lane's "remove from
 *               this device" clears it).
 *
 * ## Errors
 *
 * A browser may refuse IndexedDB outright (private mode, a blocked origin).
 * Every call therefore resolves with a value or rejects with a plain `Error`
 * whose message is a sentence — never the raw DOMException, whose name would
 * leak into a panel either way. Nothing here throws synchronously, so a caller
 * can always `.catch()`.
 *
 * `navigator.storage.persist()` is asked for once per page load, because a
 * take held in evictable storage is a take that can be lost; the answer is
 * ignored and a refusal is not an error.
 *
 * @type {string}
 */
export const TAKE_STORE_SCRIPT = [
  "(function () {",
  "  'use strict';",
  "",
  "  var DB_NAME = 'studio';",
  "  var DB_VERSION = 1;",
  "  var CHUNKS = 'chunks';",
  "  var PENDING = 'pending';",
  "  var LATENCY = 'latency';",
  "  var AUDIO = 'audio';",
  "",
  "  var dbPromise = null;",
  "",
  "  function messageOf(err) {",
  "    if (err && err.message) return String(err.message);",
  "    return String(err || 'unknown reason');",
  "  }",
  "",
  "  function indexedDbOf() {",
  "    try {",
  "      return window.indexedDB || null;",
  "    } catch (err) {",
  "      return null;",
  "    }",
  "  }",
  "",
  "  // The database, opened once: version 1 creates the four stores, and a",
  "  // blocked or refused open rejects with a sentence instead of hanging.",
  "  function openDb() {",
  "    if (dbPromise) return dbPromise;",
  "    dbPromise = new Promise(function (resolve, reject) {",
  "      var factory = indexedDbOf();",
  "      if (!factory) {",
  "        dbPromise = null;",
  "        reject(new Error('This browser cannot keep takes on this device.'));",
  "        return;",
  "      }",
  "      var request = null;",
  "      try {",
  "        request = factory.open(DB_NAME, DB_VERSION);",
  "      } catch (err) {",
  "        dbPromise = null;",
  "        reject(new Error('This browser would not open its take store: ' + messageOf(err)));",
  "        return;",
  "      }",
  "      request.onupgradeneeded = function () {",
  "        var db = request.result;",
  "        if (!db.objectStoreNames.contains(CHUNKS)) db.createObjectStore(CHUNKS);",
  "        if (!db.objectStoreNames.contains(PENDING)) db.createObjectStore(PENDING);",
  "        if (!db.objectStoreNames.contains(LATENCY)) db.createObjectStore(LATENCY);",
  "        if (!db.objectStoreNames.contains(AUDIO)) db.createObjectStore(AUDIO);",
  "      };",
  "      request.onsuccess = function () {",
  "        var db = request.result;",
  "        db.onversionchange = function () {",
  "          try { db.close(); } catch (err) { /* already closed */ }",
  "          dbPromise = null;",
  "        };",
  "        resolve(db);",
  "      };",
  "      request.onerror = function () {",
  "        dbPromise = null;",
  "        reject(new Error('This browser would not open its take store.'));",
  "      };",
  "    });",
  "    return dbPromise;",
  "  }",
  "",
  "  // One transaction: work(tx, keep) runs inside it, keep(value) names what",
  "  // the promise resolves with, and an abort or an error rejects with a",
  "  // sentence.",
  "  function run(stores, mode, work) {",
  "    return openDb().then(function (db) {",
  "      return new Promise(function (resolve, reject) {",
  "        var tx = null;",
  "        try {",
  "          tx = db.transaction(stores, mode);",
  "        } catch (err) {",
  "          reject(new Error('The take store refused that: ' + messageOf(err)));",
  "          return;",
  "        }",
  "        var value = null;",
  "        var failed = false;",
  "        var fail = function () {",
  "          if (failed) return;",
  "          failed = true;",
  "          reject(new Error('The take store refused that: ' + messageOf(tx.error)));",
  "        };",
  "        tx.onerror = fail;",
  "        tx.onabort = fail;",
  "        tx.oncomplete = function () {",
  "          if (!failed) resolve(value);",
  "        };",
  "        try {",
  "          work(tx, function (next) { value = next; });",
  "        } catch (err) {",
  "          failed = true;",
  "          try { tx.abort(); } catch (abortErr) { /* already finished */ }",
  "          reject(new Error('The take store refused that: ' + messageOf(err)));",
  "        }",
  "      });",
  "    });",
  "  }",
  "",
  "  function plain(promise) {",
  "    return promise.catch(function (err) {",
  "      throw new Error(messageOf(err));",
  "    });",
  "  }",
  "",
  "  // ---- chunks ----------------------------------------------------------",
  "",
  "  function putChunk(takeId, index, bytes) {",
  "    return plain(run([CHUNKS], 'readwrite', function (tx, keep) {",
  "      var store = tx.objectStore(CHUNKS);",
  "      var request = store.put(bytes, [String(takeId), Number(index)]);",
  "      request.onsuccess = function () { keep(true); };",
  "    }));",
  "  }",
  "",
  "  function getChunk(takeId, index) {",
  "    return plain(run([CHUNKS], 'readonly', function (tx, keep) {",
  "      var store = tx.objectStore(CHUNKS);",
  "      var request = store.get([String(takeId), Number(index)]);",
  "      request.onsuccess = function () { keep(request.result || null); };",
  "    }));",
  "  }",
  "",
  "  // ---- pending uploads -------------------------------------------------",
  "",
  "  function putPending(value) {",
  "    var pending = value && typeof value === 'object' ? value : {};",
  "    if (!pending.take_id) return Promise.reject(new Error('A pending take needs its take id.'));",
  "    return plain(run([PENDING], 'readwrite', function (tx, keep) {",
  "      var store = tx.objectStore(PENDING);",
  "      var request = store.put(pending, String(pending.take_id));",
  "      request.onsuccess = function () { keep(true); };",
  "    }));",
  "  }",
  "",
  "  function listPending() {",
  "    return plain(run([PENDING], 'readonly', function (tx, keep) {",
  "      var store = tx.objectStore(PENDING);",
  "      var request = store.getAll();",
  "      request.onsuccess = function () {",
  "        keep(Array.isArray(request.result) ? request.result : []);",
  "      };",
  "    }));",
  "  }",
  "",
  "  // A finished take leaves nothing behind: its pending row goes, and so do all",
  "  // of its chunks. Deleting the row first means a crash in between leaves",
  "  // orphaned chunks, never an upload that names chunks that are gone.",
  "  function deletePending(takeId) {",
  "    var id = String(takeId);",
  "    return plain(run([PENDING, CHUNKS], 'readwrite', function (tx, keep) {",
  "      tx.objectStore(PENDING).delete(id);",
  "      var chunks = tx.objectStore(CHUNKS);",
  "      var range = null;",
  "      try {",
  "        range = window.IDBKeyRange.bound([id, 0], [id, Number.MAX_SAFE_INTEGER]);",
  "      } catch (err) {",
  "        range = null;",
  "      }",
  "      var cursorRequest = range ? chunks.openCursor(range) : chunks.openCursor();",
  "      cursorRequest.onsuccess = function () {",
  "        var cursor = cursorRequest.result;",
  "        if (!cursor) { keep(true); return; }",
  "        var key = cursor.key;",
  "        var mine = Array.isArray(key) && String(key[0]) === id;",
  "        if (mine) cursor.delete();",
  "        cursor.continue();",
  "      };",
  "    }));",
  "  }",
  "",
  "  // ---- latency ---------------------------------------------------------",
  "",
  "  function getLatency(key) {",
  "    return plain(run([LATENCY], 'readonly', function (tx, keep) {",
  "      var store = tx.objectStore(LATENCY);",
  "      var request = store.get(String(key));",
  "      request.onsuccess = function () { keep(request.result || null); };",
  "    }));",
  "  }",
  "",
  "  function putLatency(key, value) {",
  "    return plain(run([LATENCY], 'readwrite', function (tx, keep) {",
  "      var store = tx.objectStore(LATENCY);",
  "      var request = store.put(value, String(key));",
  "      request.onsuccess = function () { keep(true); };",
  "    }));",
  "  }",
  "",
  "  // ---- the audio cache -------------------------------------------------",
  "",
  "  function getAudio(takeId) {",
  "    return plain(run([AUDIO], 'readonly', function (tx, keep) {",
  "      var store = tx.objectStore(AUDIO);",
  "      var request = store.get(String(takeId));",
  "      request.onsuccess = function () { keep(request.result || null); };",
  "    }));",
  "  }",
  "",
  "  function putAudio(takeId, bytes) {",
  "    return plain(run([AUDIO], 'readwrite', function (tx, keep) {",
  "      var store = tx.objectStore(AUDIO);",
  "      var request = store.put(bytes, String(takeId));",
  "      request.onsuccess = function () { keep(true); };",
  "    }));",
  "  }",
  "",
  "  function clearAudio() {",
  "    return plain(run([AUDIO], 'readwrite', function (tx, keep) {",
  "      var store = tx.objectStore(AUDIO);",
  "      var request = store.clear();",
  "      request.onsuccess = function () { keep(true); };",
  "    }));",
  "  }",
  "",
  "  // A take in evictable storage is a take that can be lost, so the page asks",
  "  // once to have its storage kept. The answer is the browser's business.",
  "  try {",
  "    var storage = typeof navigator !== 'undefined' && navigator ? navigator.storage : null;",
  "    if (storage && typeof storage.persist === 'function') {",
  "      var asked = storage.persist();",
  "      if (asked && typeof asked.catch === 'function') asked.catch(function () {});",
  "    }",
  "  } catch (err) {",
  "    // A browser that refuses the request keeps its storage as it was.",
  "  }",
  "",
  "  window.StudioTakeStore = {",
  "    putChunk: putChunk,",
  "    getChunk: getChunk,",
  "    listPending: listPending,",
  "    putPending: putPending,",
  "    deletePending: deletePending,",
  "    getLatency: getLatency,",
  "    putLatency: putLatency,",
  "    getAudio: getAudio,",
  "    putAudio: putAudio,",
  "    clearAudio: clearAudio",
  "  };",
  "})();",
].join("\n");